#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include "crc_tags.h"

static int failures = 0;
static int total = 0;

static void fail(const char *label, const char *msg) {
    failures++;
    if (failures <= 8) printf("  %s: %s\n", label, msg);
}

static void check_err(const char *label, int rc) {
    total++;
    if (rc == 0) fail(label, "expected an error");
}

static void check_str(const char *label, int rc, const char *got, const char *want) {
    total++;
    char msg[600];
    if (rc != 0) { fail(label, "unexpected error"); return; }
    if (strcmp(got, want) != 0) {
        snprintf(msg, sizeof msg, "want \"%s\", got \"%s\"", want, got);
        fail(label, msg);
    }
}

static void check_int(const char *label, int rc, int64_t got, int64_t want) {
    total++;
    char msg[200];
    if (rc != 0) { fail(label, "unexpected error"); return; }
    if (got != want) {
        snprintf(msg, sizeof msg, "want %lld, got %lld", (long long) want, (long long) got);
        fail(label, msg);
    }
}

int main(void) {
    {  int64_t got = (int64_t) crc_tags_crc12("123456789"); check_int("crc12#0", 0, got, INT64_C(3931)); }
    {  uint32_t out = 0; int rc = crc_tags_crc12_hex("313233", &out); check_int("crc12_hex#1", rc, (int64_t) out, INT64_C(1285)); }
    { const char *xs0[] = {"12", "345", "6789"}; int64_t got = (int64_t) crc_tags_crc12_parts(xs0, 3); check_int("crc12_parts#2", 0, got, INT64_C(3931)); }
    {  char out[8192]; int rc = crc_tags_tag_make("AB", INT64_C(1), out, sizeof out); check_str("tag_make#3", rc, out, "AB-00001-BE8"); }
    {  int64_t got = (int64_t) crc_tags_tag_check("AB-00001-000"); check_int("tag_check#4", 0, got, INT64_C(0)); }
    {  int64_t out = 0; int rc = crc_tags_tag_number("AB-00007-BD4", &out); check_int("tag_number#5", rc, (int64_t) out, INT64_C(7)); }
    {  char out[8192]; int rc = crc_tags_tag_next("AB-00007-BD4", out, sizeof out); check_str("tag_next#6", rc, out, "AB-00008-BB2"); }
    {  int64_t got = (int64_t) crc_tags_crc12(""); check_int("crc12#7", 0, got, INT64_C(0)); }
    {  int64_t got = (int64_t) crc_tags_crc12("a"); check_int("crc12#8", 0, got, INT64_C(3023)); }
    {  int64_t got = (int64_t) crc_tags_crc12("A"); check_int("crc12#9", 0, got, INT64_C(650)); }
    if (failures) {
        printf("%d of %d vectors failed\n", failures, total);
        return 1;
    }
    printf("ok %d vectors\n", total);
    return 0;
}

