import re

_TAG = re.compile(r"([A-Z]{2,4})-([0-9]{5})-([0-9A-F]{3})")
_HEX = re.compile(r"(?:[0-9A-Fa-f]{2})*")


def _crc(data, crc=0):
    for b in data:
        crc ^= b << 4
        for _ in range(8):
            crc = ((crc << 1) ^ 0x80F) & 0xFFF if crc & 0x800 else (crc << 1) & 0xFFF
    return crc


def crc12(text):
